    lesson["interactive"] = {"type": "scientific-investigation", "goal": "以長期資料與衝擊鏈分析 Nb-Ⅳ-2：氣候變遷的全球衝擊，並寫出有尺度、證據與限制的結論。", "scenario": "在全球趨勢、地方暴露與調適策略三張資料卡間切換，先判斷尺度，再把危害、暴露、脆弱度與應變能力連成可查證推理。", "variables": [{"symbol": "H", "meaning": "危害強度與時間尺度"}, {"symbol": "E", "meaning": "暴露的人、土地、生態或設施"}, {"symbol": "V", "meaning": "脆弱度與應變能力"}], "steps": [{"id": "step-1", "prompt": "資料卡是全球長期趨勢、地方短期事件，還是兩者混合？先標出什麼？", "options": ["期間、地點、指標與基準期", "只看標題顏色", "先選損失最大的城市"], "answer": "A", "feedback": "沒有時間與空間尺度，就不能把事件、地方趨勢和全球訊號放在同一層比較。"}, {"id": "step-2", "prompt": "同一升溫幅度在兩地造成不同損失，應如何拆解？", "options": ["比較危害、暴露、脆弱度與應變能力", "假設兩地結果必然相同", "只用緯度取代地方資料"], "answer": "A", "feedback": "氣候危害只是風險的一部分，人口、地形、設施和制度會改變實際衝擊。"}, {"id": "step-3", "prompt": "要判斷極端洪水是否帶有氣候訊號，哪種證據較合適？", "options": ["長期序列、極端值分析、歸因與土地利用資料的組合", "只放一張災後照片", "只挑最嚴重的一年"], "answer": "A", "feedback": "多重且可比較的證據能把氣候因素與地形、都市化、排水等替代因素分開。"}, {"id": "step-4", "prompt": "提出濕地或能源轉型方案時，還要加上什麼才不是口號？", "options": ["效益、限制、分配影響與可追蹤指標", "宣稱單一措施消除所有風險", "只列措施名稱，不說如何驗證"], "answer": "A", "feedback": "完整方案必須說明誰受益、誰承擔成本、何時有效，以及如何用資料修正。"}]}
    lesson["updatedAt"] = TODAY; lesson["reviewStatus"] = "draft"
    for idx, prompt, options, answer, explanation, strategy in ITEMS:
        p = QUESTION_DIR / f"question-science-content-nb-iv-2-{idx}.json"; q = json.loads(p.read_text(encoding="utf-8"))
        q["prompt"] = prompt; q["options"] = [{"id": chr(65+j), "text": text} for j, text in enumerate(options)]
        q["answer"] = {"value": answer, "explanation": f"{explanation} 正確答案為選項 {answer}：「{options[ord(answer)-65]}」。"}; q["examPatternRefs"] = refs()
        q["provenance"] = {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然／理化試題的全球環境變化、資料判讀、災害與調適能力方向；本題只作 pattern-only 改寫。", "authoringNote": COMMON + " 待第二輪 AI／Terra 內容複核。"}
        q["solutionStrategy"] = strategy; q["solutionSteps"] = ["圈出現象、時間尺度、地點與受影響系統。", "把危害、暴露、脆弱度、應變能力與替代因素分欄。", "依資料連結機制，避免把相關性直接寫成唯一因果。", "檢查選項是否超出資料尺度、忽略對照或誇大措施效果。", "回查題幹核對答案、限制與下一項證據。"]; q["reviewStatus"] = "draft"; q["updatedAt"] = TODAY
        p.write_text(json.dumps(q, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    REPORT.write_text(json.dumps({"unit": "Nb-Ⅳ-2：氣候變遷的全球衝擊", "lessonId": lesson["id"], "status": "first-pass-ai-review-complete", "reviewStatus": "draft", "checkedQuestions": len(ITEMS), "checks": {"unitSpecificOriginalContent": True, "threeVersionResearchRecords": True, "threePublicSchoolExamPatternSources": True, "answersAndDetailedSteps": True, "interactivePredictionManipulationExplanation": True, "terraSecondPass": "pending"}, "reviewedAt": TODAY, "note": COMMON + " 版本融合、逐題學科內容 QA、Terra 第二輪與正式發布尚未完成，因此教材與題目維持 draft。"}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
